void check(bool b,const char* s){if(!b)throw std::runtime_error(s);}
template<class F>void rejects(F f){bool hit=false;try{f();}catch(const std::exception&){hit=true;}check(hit,"expected rejection");}
void balance(const Supply& f,const ParticleSystem& w){auto r=f.report();double m=0;for(auto& p:w.particles)m+=3.14159265358979323846/6*std::pow(p.diameter_m,3)*p.material.density_kg_m3;
 check(r.planned==r.inserted+r.pending+r.future&&r.requested==r.inserted+r.pending,"count balance");
 check(std::abs(m-r.inserted_mass)<1e-10&&std::abs(r.mass_error)<1e-10,"independent supply mass balance");
 for(std::size_t i=0;i<w.particles.size();++i){const auto& p=w.particles[i];check(box_contacts(p,w.boxes).empty(),"no wall overlap");for(std::size_t j=0;j<i;++j){const auto& q=w.particles[j];check(std::hypot(p.position_m.x-q.position_m.x,p.position_m.y-q.position_m.y,p.position_m.z-q.position_m.z)>=(p.diameter_m+q.diameter_m)/2,"no forced pair overlap");}}
}
template<class F>auto wait(Worker& w,F f){auto end=std::chrono::steady_clock::now()+std::chrono::seconds(15);while(std::chrono::steady_clock::now()<end){auto s=w.snapshot();if(f(*s))return s;std::this_thread::sleep_for(std::chrono::milliseconds(1));}throw std::runtime_error("worker timeout");}
